Translate("frFR", "city-of-dalaran-dungeon", {
	title = "Donjon de la cité de Dalaran",
	aliases = { "les salles troublées de Dalaran" },
	sections = {
		{
			title = "Résumé",
			text = [=[Sous le visage éclatant de la {link:city-of-dalaran}cité de Dalaran{/link} rebâtie s'étend une cité que ses maîtres ne commandent plus tout à fait. Les mages ont relevé {link:dalaran}Dalaran{/link} derrière leur grande barrière, et quand la barrière est tombée, ils ont ouvert leurs portes comme si tout allait bien. Il n'en est rien. Par endroits, la cité restaurée a échappé au contrôle du {link:kirin-tor}Kirin Tor{/link}. Des sorts se retournent contre ceux qui les lancent, des assemblages créés pour servir errent librement, le mana brut a pris forme et faim, et quelque chose de démoniaque a pris racine là où aucun démon ne devrait se trouver. Le Kirin Tor a besoin d'aide, et il est trop fier pour la demander à voix haute.]=],
		},
		{
			title = "Origines",
			text = [=[{link:dalaran}Dalaran{/link} a déjà été brisée. Pendant la {link:third-war}Troisième Guerre{/link}, {link:archimonde}Archimonde{/link} détruisit la cité d'un seul sort, et les survivants passèrent des années à la rebâtir en secret. Une telle œuvre ne pouvait s'accomplir sans de vastes déversements de {link:arcane-magic}magie des arcanes{/link}, sans protections posées sur d'autres protections, ni sans serviteurs liés par enchantement. Combien de ce pouvoir ancien s'attarde encore dans les pierres, et combien de l'ombre du seigneur démon, nul hors de l'ordre ne saurait le dire. Les troubles intérieurs ont commencé avant la chute de la barrière. Nul n'a encore dit s'ils en sont la cause.]=],
		},
		{
			title = "De nos jours",
			text = [=[Les enquêteurs du {link:kirin-tor}Kirin Tor{/link} parlent d'une perturbation qui s'aggrave de jour en jour, et de découvertes faites sur un pylône qu'ils ne savent pas encore expliquer. Leurs ordres sont de garder la cité calme. Pendant ce temps, les salles d'en bas se sont remplies de choses qui ne devraient pas être. Parmi elles se trouvent un lieu appelé {link:fel-grove}Fel Grove{/link}, où la magie gangrenée s'est infiltrée dans le bois vivant, et des ombres errantes de défunts.]=],
		},
		{
			title = "Ceux qui demeurent ici",
			text = [=[• {b}L'{link:arcane-anomaly}Arcane Anomaly{/link}.{/b} Une magie qui s'est affranchie de son schéma.
• {b}Le {link:fel-ancient}Fel Ancient{/link}.{/b} Un grand être de bois et de racines, corrompu par la magie gangrenée.
• {b}Le {link:mana-devourer}Mana Devourer{/link}, le {link:mana-elemental}Mana Elemental{/link} et le {link:mana-wraith}Mana Wraith{/link}.{/b} Des créatures de mana brut, nées de la puissance débordante de la cité.
• {b}L'{link:unstable-sentinel}Unstable Sentinel{/link}.{/b} Un assemblage gardien qui n'obéit plus.
• {b}La {link:shade-of-the-archmage}Shade of the Archmage{/link}.{/b} Le fantôme de l'un des propres mages de {link:dalaran}Dalaran{/link}.
• {b}{link:lyn-the-ignored}Lyn the Ignored{/link}.{/b} Une figure dont nul n'a pris la peine d'écouter l'histoire.
• {b}{link:atrexis-the-grave-knight}Atrexis, le chevalier de la tombe{/link}.{/b} Un chevalier de la tombe, venu dans la cité des mages.]=],
		},
	},
})

Translate("frFR", "fel-grove", {
	title = "Fel Grove",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Fel Grove se trouve dans {link:city-of-dalaran-dungeon}les salles troublées de Dalaran{/link}. Son nom dit ce que les mages redoutent le plus d'entendre : que la magie gangrenée, la puissance de la {link:burning-legion}Légion ardente{/link}, a trouvé un foyer dans la cité du {link:kirin-tor}Kirin Tor{/link}, et qu'elle a touché des choses qui poussent. Aucune archive n'explique encore comment un bosquet a pu pousser au cœur de {link:dalaran}Dalaran{/link}, ni comment il a été souillé. C'est peut-être l'un des lieux où l'énergie démoniaque qui trouble la cité est la plus forte.]=],
		},
	},
})

Translate("frFR", "arcane-anomaly", {
	title = "Arcane Anomaly",
	subtitle = "La magie déchaînée",
	hint = [=[Affrontez le nœud vivant de magie qui s'est libéré dans les salles de Dalaran.]=],
	allegiance = "Aucune",
	sections = {
		{
			title = "Résumé",
			text = [=[L'Arcane Anomaly est une magie qui a perdu sa forme et trouvé une volonté propre. Le {link:kirin-tor}Kirin Tor{/link} a rebâti sa cité enchantement après enchantement, et tous ces sorts n'ont pas tenu. Certains se sont égarés. Celui-ci est devenu quelque chose qui se meut et qui frappe.]=],
		},
		{
			title = "Importance",
			text = [=[L'Anomaly est le signe le plus clair de ce qui s'est déréglé à {link:dalaran}Dalaran{/link}. La propre puissance de la cité a commencé à se retourner contre elle.]=],
		},
		{
			title = "Ce que l'on ignore",
			text = [=[Aucune archive ne dit encore quel sort a donné naissance à l'Anomaly, ni depuis combien de temps elle erre dans la cité.]=],
		},
	},
})

Translate("frFR", "fel-ancient", {
	title = "Fel Ancient",
	subtitle = "Le gardien corrompu",
	hint = [=[Affrontez le géant souillé de racines et de bois dans les salles troublées de Dalaran.]=],
