	sections = {
		{
			title = "Résumé",
			text = [=[Le Fel Ancient porte le nom des anciens, les grands esprits de bois et de racines qui gardent les forêts du monde. Celui-ci a été touché par la magie gangrenée. C'est une étrange chose à trouver dans une cité de mages humains, et une chose dangereuse. Là où la magie gangrenée prend racine, la {link:burning-legion}Légion ardente{/link} est rarement loin.]=],
		},
		{
			title = "Importance",
			text = [=[Le Fel Ancient donne forme à l'énergie démoniaque que le {link:kirin-tor}Kirin Tor{/link} a sentie dans ses rues.]=],
		},
		{
			title = "Ce que l'on ignore",
			text = [=[Aucune archive ne dit encore comment un ancien est venu à {link:dalaran}Dalaran{/link}, ni ce qui l'a corrompu.]=],
