})

Translate("frFR", "mana-devourer", {
	title = "Mana Devourer",
	subtitle = "La faim de la cité",
	hint = "Affrontez la créature qui se nourrit de la magie de Dalaran.",
	allegiance = "Aucune",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Mana Devourer se nourrit de magie. {link:dalaran}Dalaran{/link} est une cité faite de sorts, et ses pierres et ses protections sont lourdes de mana. Pour une telle créature, la cité est un festin. Partout où il passe, les enchantements des mages s'affaiblissent, et lui se renforce.]=],
		},
		{
			title = "Importance",
			text = [=[Le Devourer est l'une des trois créatures de mana qui troublent la cité. Sa faim menace la magie même qui fait tenir la nouvelle {link:dalaran}Dalaran{/link}.]=],
		},
		{
			title = "Ce que l'on ignore",
			text = [=[Aucune archive ne dit encore d'où vient le Devourer, ni s'il a été attiré par la cité ou s'il y est né.]=],
		},
	},
})

Translate("frFR", "mana-elemental", {
	title = "Mana Elemental",
	subtitle = "La magie brute faite forme",
	hint = [=[Affrontez l'être de mana brut qui s'agite dans les salles de Dalaran.]=],
	allegiance = "Aucune",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Mana Elemental est du mana brut qui a pris forme. Les mages de {link:dalaran}Dalaran{/link} ont toujours lié des élémentaires à leur service, et durant les années de la reconstruction, leurs serviteurs furent nombreux. Celui-ci ne sert personne. Le {link:kirin-tor}Kirin Tor{/link} n'a pas dit s'il fut jadis lié puis s'est libéré, ou si la puissance débordante de la cité l'a appelé à l'existence.]=],
		},
		{
			title = "Importance",
			text = [=[Le Mana Elemental est l'une des trois créatures de mana qui troublent la cité.]=],
		},
		{ title = "Ce que l'on ignore", text = "Aucune archive ne raconte encore son histoire." },
	},
})

Translate("frFR", "mana-wraith", {
	title = "Mana Wraith",
	subtitle = "Le mana sans repos",
	hint = [=[Affrontez le spectre de mana qui hante les salles de Dalaran.]=],
	allegiance = "Aucune",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Mana Wraith dérive à travers {link:city-of-dalaran-dungeon}les salles troublées de Dalaran{/link} comme un fantôme fait de magie. Son nom unit deux choses que le {link:kirin-tor}Kirin Tor{/link} redoute : la puissance brute qu'il commande, et les morts sans repos. C'est peut-être un esprit qui s'est nourri de mana jusqu'à ce qu'il ne reste plus de lui que du mana. C'est peut-être quelque chose de plus étrange.]=],
		},
		{
			title = "Importance",
			text = [=[Le Mana Wraith est l'une des trois créatures de mana qui troublent la cité.]=],
		},
		{
			title = "Ce que l'on ignore",
			text = [=[Aucune archive ne dit encore ce que fut le Wraith auparavant, s'il fut jamais autre chose.]=],
		},
	},
})

Translate("frFR", "unstable-sentinel", {
	title = "Unstable Sentinel",
	subtitle = "Le gardien qui refuse d'obéir",
	hint = [=[Affrontez l'assemblage gardien qui a échappé au contrôle de ses maîtres.]=],
	allegiance = "Aucune",
	sections = {
		{
			title = "Résumé",
			text = [=[L'Unstable Sentinel fut créée pour garder. Le {link:kirin-tor}Kirin Tor{/link} remplit sa cité de sentinelles arcaniques qui veillent sans repos. Cette sentinelle ne lui répond plus. Ses enchantements sont devenus instables, et un gardien qui ne distingue plus l'ami de l'ennemi est plus dangereux que n'importe quel voleur.]=],
		},
		{
			title = "Importance",
			text = [=[La Sentinel est l'un des assemblages qui ont rompu leurs liens dans la cité restaurée.]=],
		},
		{
			title = "Ce que l'on ignore",
			text = [=[Aucune archive ne dit encore ce que la Sentinel gardait autrefois.]=],
		},
	},
})

Translate("frFR", "shade-of-the-archmage", {
	title = "Shade of the Archmage",
	subtitle = "Un fantôme du Kirin Tor",
	hint = [=[Affrontez le fantôme d'un archimage qui arpente encore les salles de Dalaran.]=],
	allegiance = "Aucune",
	sections = {
		{
			title = "Résumé",
			text = [=[La Shade of the Archmage est le fantôme de l'un des propres mages de {link:dalaran}Dalaran{/link}. Beaucoup de membres du {link:kirin-tor}Kirin Tor{/link} périrent quand le {link:scourge}Fléau{/link} et {link:archimonde}Archimonde{/link} s'abattirent sur la cité pendant la {link:third-war}Troisième Guerre{/link}. Celui-ci n'a pas trouvé le repos. Il arpente les salles de la cité qu'il servit, et il n'accueille pas les vivants.]=],
		},
		{
			title = "Importance",
			text = [=[La Shade rappelle que {link:dalaran}Dalaran{/link} fut rebâtie sur les tombes de ses défenseurs.]=],
		},
		{
			title = "Ce que l'on ignore",
			text = [=[Aucune archive ne nomme encore l'archimage que fut la Shade, ni ne dit pourquoi l'esprit ne peut trouver le repos. Le {link:kirin-tor}Kirin Tor{/link}, s'il le sait, ne l'a pas dit.]=],
		},
	},
})

Translate("frFR", "lyn-the-ignored", {
	title = "Lyn the Ignored",
	subtitle = "Nul ne l'écoute",
	hint = [=[Cherchez à Dalaran la figure que personne n'a jamais écoutée.]=],
	allegiance = "Aucune",
	aliases = { "Lyn" },
	sections = {
		{
			title = "Résumé",
			text = [=[Lyn the Ignored porte un nom qui sonne comme un grief. C'est un nom étrange à entendre à {link:dalaran}Dalaran{/link}, une cité de mages fiers où le rang et le savoir comptent plus que tout. Qui que fût Lyn, personne n'ignore plus Lyn à présent. Dans les salles troublées sous la cité rebâtie, Lyn est devenue l'une des puissances que le {link:kirin-tor}Kirin Tor{/link} ne peut plus négliger.]=],
		},
		{
			title = "Importance",
			text = [=[Lyn est l'un des mystères les plus étranges de la cité restaurée. Le nom seul laisse deviner une histoire que le {link:kirin-tor}Kirin Tor{/link} n'a pas racontée.]=],
		},
		{
			title = "Ce que l'on ignore",
			text = [=[Aucune archive ne dit encore qui était Lyn, qui ignorait Lyn, ni pourquoi. Tout ce qui, dans cette entrée, dépasse le nom n'est qu'une lecture de ce nom.]=],
		},
	},
})

Translate("frFR", "atrexis-the-grave-knight", {
	title = "Atrexis, le chevalier de la tombe",
	subtitle = "Le chevalier de la tombe",
	hint = [=[Affrontez le chevalier de la tombe venu dans les salles de Dalaran.]=],
	allegiance = "Aucune",
	aliases = { "Atrexis" },
	sections = {
		{
			title = "Résumé",
			text = [=[Atrexis est appelé le chevalier de la tombe. Ce nom appartient aux morts, non aux mages, et il est sombre à entendre à {link:dalaran}Dalaran{/link}. La cité a déjà connu des chevaliers de la mort : le {link:scourge}Fléau{/link} qui la détruisit marchait sous des champions revenus de la tombe. Ce qu'est Atrexis, et qui Atrexis sert, le {link:kirin-tor}Kirin Tor{/link} ne l'a pas dit.]=],
		},
		{
			title = "Importance",
			text = [=[Atrexis est la plus guerrière des puissances de la cité troublée, un chevalier là où les autres sont des sorts et des esprits.]=],
		},
		{
			title = "Ce que l'on ignore",
			text = [=[Aucune archive ne raconte encore l'histoire d'Atrexis, ni comment un chevalier de la tombe en vint à marcher parmi les mages.]=],
		},
	},
})
